public static int nullSafeHashCode(long[] array){
    if (array == null) {
        return 0;
    }
    int result = 1;
    for (long value : array) {
        result = 31 * result + (int) (value ^ (value >>> 32));
    }
    return result;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) return null;
    TreeNode<T> newParent = node.left;
    if (newParent == null) return node;
    // detach newParent's right subtree and attach it as node's left subtree
    node.left = newParent.right;
    if (newParent.right != null) newParent.right.parent = node;
    // pivot node under newParent
    newParent.right = node;
    // rewire parent references
    newParent.parent = node.parent;
    node.parent = newParent;
    return newParent;
}

