public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file is null");
    }
    if (!file.exists()) {
        throw new IOException("File does not exist: " + file);
    }
    if (file.isDirectory()) {
        deleteDirectoryOnExit(file);
    } else if (file.isFile()) {
        file.deleteOnExit();
    } else {
        throw new IOException("Cannot delete unknown file type: " + file);
    }
}

/**
 * Registers the given directory and all its contents for deletion on JVM exit.
 * @param dir the directory to delete on exit
 * @throws IOException if an I/O error occurs
 */
private static void deleteDirectoryOnExit(File dir) throws IOException {
    File[] files = dir.listFiles();
    if (files == null) {
        // Treat null as an I/O error; listFiles() returns null if dir is not a directory or an I/O error occurs.
        throw new IOException("Failed to list contents of directory: " + dir);
    }
    for (File f : files) {
        if (f.isDirectory()) {
            deleteDirectoryOnExit(f);
        } else if (f.isFile()) {
            f.deleteOnExit();
        } else {
            throw new IOException("Encountered unknown file type while deleting: " + f);
        }
    }
    dir.deleteOnExit();
}

