protected int findByte(byte value, int pos) {
    // Ensure the buffer exists and the starting position is valid.
    if (buffer == null) {
        return -1;
    }
    int len = buffer.length;
    if (pos < 0 || pos >= len) {
        return -1;
    }
    // Search from the starting position to the end of the buffer.
    for (int i = pos; i < len; i++) {
        if (buffer[i] == value) {
            return i;
        }
    }
    // Not found
    return -1;
}

public static <T> int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    if (out == null) throw new IllegalArgumentException("OutputStream cannot be null");
    if (message == null) throw new IllegalArgumentException("Message cannot be null");
    if (schema == null) throw new IllegalArgumentException("Schema cannot be null");
    if (buffer == null) buffer = LinkedBuffer.allocate(256);
    buffer.clear();
    schema.writeTo(buffer, message);
    int size = buffer.size();
    byte[] data = buffer.toByteArray();
    CodedOutputStream coded = CodedOutputStream.newInstance(out);
    coded.writeRawVarint32(size);
    coded.writeRawBytes(data);
    coded.flush();
    return size;
}

