public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    try {
        if (!(genericType instanceof ParameterizedType)) {
            return null;
        }
        ParameterizedType pType = (ParameterizedType) genericType;
        Type[] typeArguments = pType.getActualTypeArguments();
        Class<?>[] resolved = new Class<?>[typeArguments.length];
        for (int i = 0; i < typeArguments.length; i++) {
            Type arg = typeArguments[i];
            if (arg instanceof Class<?>) {
                resolved[i] = (Class<?>) arg;
            } else if (arg instanceof ParameterizedType) {
                // If the argument itself is a parameterized type, we return its raw type
                Type raw = ((ParameterizedType) arg).getRawType();
                if (raw instanceof Class<?>) {
                    resolved[i] = (Class<?>) raw;
                } else {
                    return null;
                }
            } else {
                // Unsupported type (WildcardType, TypeVariable, GenericArrayType, etc.)
                return null;
            }
        }
        return resolved;
    } catch (Exception e) {
        // Any reflective or casting problems result in null
        return null;
    }
}

