void insertBefore(Bucket bucket) {
    if (bucket == null) {
        throw new IllegalArgumentException("bucket cannot be null");
    }
    try {
        // Link the new bucket back to this bucket
        bucket.prev = this;
        // Link this bucket forward to the new bucket
        this.next = bucket;
        // If this bucket had a previous bucket, adjust its next reference
        if (this.prev != null) {
            this.prev.next = this;
        }
