    }
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Defensive copy for result
    Mappings diff = new Mappings();
    if (mappings == null) {
        return diff;
    }
    try {
        // Retrieve current mapping for the given table
        Mappings current = this.getCurrentMapping(tableName);
        if (current == null) {
            // Nothing to compare against; return all input fields excluding _source
            for (Map.Entry<String, FieldMapping> entry : mappings.getFields().entrySet()) {
                if (!"_source".equals(entry.getKey())) {
                    diff.addField(entry.getKey(), entry.getValue());
                }
            }
            return diff;
        }

        // Compare each field in the input mapping against the current mapping
        for (Map.Entry<String, FieldMapping> entry : mappings.getFields().entrySet()) {
            String fieldName = entry.getKey();
            if ("_source".equals(fieldName)) {
                // Skip _source to avoid update conflicts
                continue;
            }
            if (!current.getFields().containsKey(fieldName)) {
                // Field missing in current mapping; add to diff
                diff.addField(fieldName, entry.getValue());
            }
        }
    } catch (Exception e) {
        // In case of any failure, return an empty diff to avoid propagating errors
        diff.clear();
    }
    return diff;
}

