static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        return timeBucket;
    }
    long year = timeBucket / 10000L;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;
    long newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + newDay;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null){
        throw new NullPointerException("str must not be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()){
        throw new IllegalArgumentException("index and len must refer to a valid substring");
    }
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++){
        char ch = str.charAt(i);
        if (ch < 0x80){
            size += 1;
        } else if (ch < 0x800){
            size += 2;
        } else if (Character.isHighSurrogate(ch)){
            // Check if pair exists within range
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))){
                // Code point is represented by surrogate pair
                size += 4;
                i++; // skip low surrogate
            } else {
                // Unmatched high surrogate, treat as replacement character (U+FFFD)
                size += 3;
            }
        } else {
            // Regular BMP character (surrogate low or any other non-surrogate)
            size += 3;
        }
    }
    return size;
}

