private java.util.Set<V> initVisibleVertices(){
    java.util.Set<V> visible = new java.util.HashSet<>();
    if (edges == null) return visible;
    for (E e : edges) {
        if (e == null) continue;
        try {
            V from = e.getSource();
            V to = e.getTarget();
            if (from != null) visible.add(from);
            if (to != null) visible.add(to);
        } catch (NoSuchMethodError | UnsupportedOperationException ignored) {
            // Fallback if edge does not have getSource()/getTarget()
            try {
                // Assume edge implements a method to get vertices as array
                Object[] verts = (Object[]) e.getClass().getMethod("getVertices").invoke(e);
                if (verts != null) {
                    for (Object v : verts) {
                        if (v != null) visible.add((V) v);
                    }
                }
            } catch (Exception ex) {
                // Unable to extract vertices; skip this edge
            }
        }
    }
    return visible;
}

