private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int len = descriptor.length();
    int i = 0;
    // Helper lambda to consume a type and return the number of slots it occupies
    java.util.function.IntBinaryOperator consumeType = (index, step) -> {
        int slots = 1;
        // Skip array brackets
        while (index < len && descriptor.charAt(index) == '[') {
            index++;
        }
        char c = descriptor.charAt(index);
        if (c == 'L') { // object type, consume until ';'
            while (index < len && descriptor.charAt(index) != ';') {
                index++;
            }
            // consume ';'
            index++;
        } else { // primitive type
            index++;
            if (c == 'J' || c == 'D') { // long or double
                slots = 2;
            }
        }
        // Return new index and slots packed into one int (high 16 bits index, low 16 bits slots)
        return ((index & 0xFFFF) << 16) | (slots & 0xFFFF);
    };

    if (descriptor.charAt(0) == '(') { // method descriptor
        i = 1;
        while (i < len && descriptor.charAt(i) != ')') {
            int packed = consumeType.applyAsInt(i, 0);
            int newIndex = (packed >> 16) & 0xFFFF;
            int slots = packed & 0xFFFF;
            i = newIndex;
            pos -= slots;
            if (pos < 0) {
                pos = 0;
                break; // or throw new IllegalStateException("Stack underflow");
            }
        }
    } else {
        int packed = consumeType.applyAsInt(i, 0);
        int newIndex = (packed >> 16) & 0xFFFF;
        int slots = packed & 0xFFFF;
        pos -= slots;
        if (pos < 0) {
            pos = 0;
            // or throw new IllegalStateException("Stack underflow");
        }
    }
}

