    if (type == null) throw new IllegalArgumentException("Target type cannot be null");
    if (value == null) return null;
    boolean targetIsChar = Character.class.equals(type) || type.equals(char.class);
    if (!targetIsChar) {
        throw new Exception("Cannot convert to unsupported type: " + type.getName());
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String s = (String) value;
        if (s.isEmpty()) {
            throw new Exception("Cannot convert empty string to Character");
        }
        return s.charAt(0);
    }
    if (value instanceof Number) {
        int i = ((Number) value).intValue();
        return Character.valueOf((char) i);
    }
    throw new Exception("Unsupported conversion from type: " + value.getClass().getName());
}

