private int deleteInactiveRecursively(Category node) {
    if (node == null) {
        return 0;
    }
    int removed = 0;
    List<Category> children = node.getChildren();
    // Use an iterator to safely remove while iterating
    Iterator<Category> it = children.iterator();
    while (it.hasNext()) {
        Category child = it.next();
        if (!child.isActive()) {
            // Entire subtree under this inactive node is removed
            int subtreeSize = countSubtreeSize(child);
            it.remove();
            removed += subtreeSize;
        } else {
            removed += deleteInactiveRecursively(child);
        }
    }
    return removed;
}

private int countSubtreeSize(Category node) {
    if (node == null) {
        return 0;
    }
    int size = 1; // count this node
    for (Category child : node.getChildren()) {
        size += countSubtreeSize(child);
    }
    return size;
}

