final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Validate simple parameters
    if (constantPoolEntryIndex < 0 || charBuffer == null) {
        return null;
    }
    // Assume classFileBuffer is a byte array available in this class
    if (classFileBuffer == null) {
        return null;
    }
    // The CONSTANT_Utf8 entry format:
    // tag (1), length (2 bytes), bytes (length bytes)
    // Ensure we have enough data for tag and length
    if (constantPoolEntryIndex + 3 > classFileBuffer.length) {
        return null;
    }
    // Verify tag is CONSTANT_Utf8 (value 1)
    if (classFileBuffer[constantPoolEntryIndex] != 1) {
        return null;
    }
    // Read unsigned short length
    int length = ((classFileBuffer[constantPoolEntryIndex + 1] & 0xFF) << 8)
               | (classFileBuffer[constantPoolEntryIndex + 2] & 0xFF);
    // Ensure length fits buffer and we have enough bytes in classFileBuffer
    if (length > charBuffer.length ||
        constantPoolEntryIndex + 3 + length > classFileBuffer.length) {
        return null;
    }
    try {
        // Extract the UTF-8 encoded bytes
        byte[] utfBytes = new byte[length];
        System.arraycopy(classFileBuffer, constantPoolEntryIndex + 3, utfBytes, 0, length);
        // Convert to String using standard UTF-8 encoding
        return new String(utfBytes, "UTF-8");
    } catch (Exception e) {
        return null;
    }
}

