public double vertexWeight(Set<V> v) {
    // Defensive checks
    if (v == null || v.isEmpty()) {
        return 0.0;
    }
    // Assume the containing class has a field named 'graph'
    // of type Graph<V, ? extends DefaultWeightedEdge>.
    // If the graph is not available, return 0.
    if (graph == null) {
        return 0.0;
    }
    try {
        double sum = 0.0;
        Set<?> seen = new java.util.HashSet<>();
        // Iterate over all edges once
        for (Object eObj : graph.edgeSet()) {
            @SuppressWarnings("unchecked")
            DefaultWeightedEdge e = (DefaultWeightedEdge) eObj;
            if (!seen.add(e)) {
                continue; // already processed
            }
            V source = graph.getEdgeSource(e);
            V target = graph.getEdgeTarget(e);
            boolean sourceIn = v.contains(source);
            boolean targetIn = v.contains(target);
            // Include edge if it connects one vertex in the set to one outside
            if (sourceIn ^ targetIn) {
                sum += graph.getEdgeWeight(e);
            }
        }
        return sum;
    } catch (Exception ex) {
        // In case of any unexpected runtime error, return 0.0
        return 0.0;
    }
}

