private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    /* Adjust links for previous node or update head if node is the first */
    if (node.prev != null) {
        node.prev.next = node.next;
    } else {
        head = node.next;
    }

    /* Adjust links for next node or update tail if node is the last */
    if (node.next != null) {
        node.next.prev = node.prev;
    } else {
        tail = node.prev;
    }

    /* Clean up the removed node to aid garbage collection */
    node.next = null;
    node.prev = null;

    /* Decrement the list size */
    size--;

    return true;
}

