private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null) {
        throw new IllegalArgumentException("bounds cannot be null");
    }
    int size = bounds.size();
    List<Integer> suffix = new ArrayList<>(size);
    long sum = 0;
    for (int i = size - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds element at index " + i + " is null");
        }
        sum += val;
        suffix.add(0, (int)sum);
    }
    long totalSum = sum;
    return new Pair<>(suffix, totalSum);
}

public static final <V>void reverse(V[] arr,int from,int to){
    if(arr==null){
        throw new IllegalArgumentException("array cannot be null");
    }
    if(from<0 || to>=arr.length || from>to){
        throw new IllegalArgumentException("invalid from/to range");
    }
    int left=from;
    int right=to;
    while(left<right){
        V temp=arr[left];
        arr[left]=arr[right];
        arr[right]=temp;
        left++;
        right--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    // Check for null or self-move
    if (list == null || list == this) {
        return;
    }
    // If source list is empty, nothing to do
    if (list.size == 0) {
        return;
    }
    // Save source references
    ListNode<E> srcHead = list.head;
    ListNode<E> srcTail = list.tail;

    // Attach the nodes to the destination list
    if (this.tail == null) {
        // Destination is empty
        this.head = srcHead;
        this.tail = srcTail;
    } else {
        // Connect tail to source head
        this.tail.next = srcHead;
        if (srcHead != null) {
            srcHead.prev = this.tail;
        }
        this.tail = srcTail;
    }
    this.size += list.size;

    // Clear source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private static boolean startsWith(final String str,final String prefix,final boolean ignoreCase){
    if (str == null) return prefix == null;
    if (prefix == null) return false;
    int prefixLen = prefix.length();
    if (str.length() < prefixLen) return false;
    if (ignoreCase) {
        for (int i = 0; i < prefixLen; i++) {
            char c1 = str.charAt(i);
            char c2 = prefix.charAt(i);
            if (Character.toLowerCase(c1) != Character.toLowerCase(c2)) {
                return false;
            }
        }
    } else {
        for (int i = 0; i < prefixLen; i++) {
            if (str.charAt(i) != prefix.charAt(i)) {
                return false;
            }
        }
    }
    return true;
}

