    }
    if (pattern == null) {
        return Filter.NEUTRAL;
    }
    java.util.regex.Matcher matcher = pattern.matcher(message);
    if (!matcher.find()) {
        return Filter.NEUTRAL;
    }
    return Filter.ACCEPT;
}

