public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }
    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        return;
    }
    try {
        // Select the row
        table.setRowSelectionInterval(row, row);

        // Scroll the table to make the selected row visible
        Rectangle cellRect = table.getCellRect(row, 0, true);
        if (cellRect != null) {
            table.scrollRectToVisible(cellRect);
        }

        // Delay repaint to ensure the newly selected row is painted
        java.awt.EventQueue.invokeLater(() -> table.repaint());
    } catch (Exception e) {
        // Swallow any unexpected exception to avoid breaking the caller
    }
}

