private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("vertices set must not be null");
    }
    // An empty or single-vertex set is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    // Iterate over all unordered pairs of distinct vertices
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 == v2) {
                continue;
            }
            // Check the presence of an edge in either direction (treat as undirected)
            if (graph.getEdge(v1, v2) == null && graph.getEdge(v2, v1) == null) {
                return false; // missing connection => not a clique
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return result;
    }
    // Collect integer values from keys (ignoring non-integer keys)
    List<Integer> sorted = new ArrayList<>();
    for (K k : keys){
        if (k instanceof Integer){
            sorted.add((Integer) k);
        }
    }
    Collections.sort(sorted);
    // For each original key, find the greatest integer value in sorted <= the key
    for (K orig : keys){
        int bound = -1; // default for no lower bound
        if (orig instanceof Integer){
            int val = (Integer) orig;
            int idx = Collections.binarySearch(sorted, val);
            if (idx >= 0){
                bound = sorted.get(idx);
            } else {
                int insertionPoint = -idx - 1;
                if (insertionPoint > 0){
                    bound = sorted.get(insertionPoint - 1);
                }
            }
        }
        result.add(bound);
    }
    return result;
}

