public static String applyRelativePath(String path, String relativePath) {
    try {
        // Handle null inputs
        if (path == null) return relativePath;
        if (relativePath == null) return path;
        if (relativePath.isEmpty()) return path;

        // If relativePath itself starts with a slash, treat it as an absolute path
        if (relativePath.startsWith("/")) {
            // Normalize the absolute path relativePath
            String[] relParts = relativePath.split("/");
            java.util.List<String> parts = new java.util.ArrayList<>();
            for (String part : relParts) {
                if (part.isEmpty() || part.equals(".")) continue;
                if (part.equals("..")) {
                    if (!parts.isEmpty()) parts.remove(parts.size() - 1);
                    continue;
                }
                parts.add(part);
            }
            StringBuilder sb = new StringBuilder();
            sb.append("/");
            for (int i = 0; i < parts.size(); i++) {
                if (i > 0) sb.append('/');
                sb.append(parts.get(i));
            }
            String result = sb.toString();
            return result.isEmpty() ? "/" : result;
        }

        // Split base path and relative path into components
        String[] baseParts = path.split("/");
        java.util.List<String> result = new java.util.ArrayList<>();
        for (String part : baseParts) {
            if (!part.isEmpty()) {
                result.add(part);
            }
        }

        String[] relParts = relativePath.split("/");
        for (String part : relParts) {
            if (part.isEmpty() || part.equals(".")) continue;
            if (part.equals("..")) {
                if (!result.isEmpty()) {
                    result.remove(result.size() - 1);
                }
                continue;
            }
            result.add(part);
        }

        // Reconstruct the final path
        StringBuilder sb = new StringBuilder();
        if (path.startsWith("/")) {
            sb.append("/");
        }
        for (int i = 0; i < result.size(); i++) {
            if (i > 0) sb.append('/');
            sb.append(result.get(i));
        }
        String finalPath = sb.toString();
        // Handle case where result is empty
        if (finalPath.isEmpty() && path.startsWith("/")) {
            return "/";
        }
        return finalPath.isEmpty() ? "." : finalPath;
    } catch (Exception e) {
        return null;
    }
}

