public boolean isExpired(long timestamp, long expiredThreshold) {
    long currentTime = System.currentTimeMillis();
    // If threshold is non-positive, we consider no metrics eligible for removal
    if (expiredThreshold <= 0) {
        return false;
    }
    // If the timestamp is in the future or timestamp is negative, treat as not expired
    if (timestamp < 0 || timestamp > currentTime) {
        return false;
    }
    // Determine if the elapsed time since timestamp exceeds the threshold
    return (currentTime - timestamp) > expiredThreshold;
}

