public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if(str == null || substring == null){
        return false;
    }
    int strLen = str.length();
    if(index < 0 || index > strLen){
        return false;
    }
    int subLen = substring.length();
    if(index + subLen > strLen){
        return false;
    }
    for(int i = 0; i < subLen; i++){
        if(str.charAt(index + i) != substring.charAt(i)){
            return false;
        }
    }
    return true;
}

public static String toString(final char ch) {
    // For 7-bit ASCII characters, we can reuse a single-character string
    // created by String.valueOf, which internally caches standard characters.
    // For non-ASCII characters we construct a new string.
    try {
        if (ch < 128) {
            return String.valueOf(ch);
        }
        return new String(new char[]{ch});
    } catch (Exception e) {
        // In the unlikely event of an exception, fall back to a new string
        return new String(new char[]{ch});
    }
}

