public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file must not be null");
    }
    if (!file.exists()) {
        throw new IOException("File does not exist: " + file);
    }
    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            // Assume each line starts with a timestamp followed by a comma
            String[] parts = line.split(",", 2);
            long timestamp;
            try {
                timestamp = Long.parseLong(parts[0].trim());
            } catch (NumberFormatException e) {
                // skip malformed lines
                continue;
            }
            boolean inRange = true;
            if (timeRanges != null && !timeRanges.isEmpty()) {
                inRange = false;
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (range == null) continue;
                    long start = Long.MIN_VALUE;
                    long end = Long.MAX_VALUE;
                    try {
                        start = range.getStartMillis();
                    } catch (Exception ignored) {}
                    try {
                        end = range.getEndMillis();
                    } catch (Exception ignored) {}
                    if (timestamp >= start && timestamp <= end) {
                        inRange = true;
                        break;
                    }
                }
            }
            if (!inRange) {
                continue;
            }
            try {
                // Attempt to create a ThreadSnapshot from the raw line
                result.add(new ThreadSnapshot(line));
            } catch (Exception e) {
                // If construction fails, try using a constructor that accepts a long timestamp and raw data
                try {
                    result.add(ThreadSnapshot.class.getConstructor(long.class, String.class).newInstance(timestamp, line));
                } catch (Exception ex) {
                    // Cannot instantiate, skip this line
                }
            }
        }
    }
    return result;
}
